const crypto = require('crypto');
const triggerItem = $('Trigger').first().json;
const auth = String(triggerItem.authorization || (triggerItem.headers && (triggerItem.headers.authorization || triggerItem.headers.Authorization)) || '');
const secret = String($input.first().json.jwtSecret || '');
const match = auth.match(/^Bearer\s+(.+)$/i);
function fail(message) {
  return [{
    json: {
      ok: false,
      success: false,
      statusCode: 401,
      message,
      error: { code: 'UNAUTHORIZED', message },
      requestId: String(($('Trigger').first().json.requestId) || ''),
    },
  }];
}
if (!match || !secret) return fail('Autenticação obrigatória.');
const token = match[1].trim();
const parts = token.split('.');
if (parts.length !== 3) return fail('Autenticação obrigatória.');
const h = parts[0];
const p = parts[1];
const s = parts[2];
const expected = crypto.createHmac('sha256', secret).update(h + '.' + p).digest('base64url');
const a = Buffer.from(s);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('Autenticação obrigatória.');
let payload;
try { payload = JSON.parse(Buffer.from(p, 'base64url').toString('utf8')); } catch { return fail('Autenticação obrigatória.'); }
const now = Math.floor(Date.now() / 1000);
if (payload.exp && now >= Number(payload.exp)) return fail('Autenticação obrigatória.');
const sessionId = payload.sessionId || payload.sid;
const userId = payload.userId || payload.sub;
if (!sessionId || !userId) return fail('Autenticação obrigatória.');
return [{ json: { ok: true, sessionId: String(sessionId), userId: String(userId), tokenId: payload.jti ? String(payload.jti) : '', requestId: String(($('Trigger').first().json.requestId) || '') } }];
